import json
def inf(id,claim,quote,page=None,frm=(),sal=None,deferred=False):
    d={"id":id,"intention":"infer","claim":claim,"quote":{"source":"paper","quote":quote},"from":list(frm)}
    if page:d["page"]=page
    if sal:d["salient"]=sal
    return d
def show(id,claim,method,mot,src,children,page=None,frm=(),sal=None,q=None,adds=None):
    m={"text":mot,"source":src}
    if q:m["quote"]={"source":"paper","quote":q}
    d={"id":id,"intention":"show","claim":claim,"method":method,"motivation":m,"children":children,"from":list(frm)}
    if page:d["page"]=page
    if sal:d["salient"]=sal
    return d

